describe('Accessibility: Prefers Reduced Motion', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the app
    });

    it('should respect prefers-reduced-motion setting when enabled', () => {
        cy.setPrefersReducedMotion(true);
        cy.reload();
        cy.get('body').should('have.class', 'reduced-motion'); // Assuming the app adds a class for reduced motion
        cy.get('.animated-element').should('not.have.css', 'animation'); // Check that animations are disabled
    });

    it('should not apply reduced motion when setting is disabled', () => {
        cy.setPrefersReducedMotion(false);
        cy.reload();
        cy.get('body').should('not.have.class', 'reduced-motion'); // Check that the class is not present
        cy.get('.animated-element').should('have.css', 'animation'); // Check that animations are enabled
    });
});
